const items = $input.all();

return items.map(item => {
  const body = item.json.body ?? item.json;

  if (typeof body.sample_id !== "string" ||
      !body.sample_id.trim()) {
    throw new Error("Missing or invalid sample_id");
  }

  if (typeof body.code !== "string" ||
      !body.code.trim()) {
    throw new Error("Missing or invalid code");
  }

  return {
    json: {
      sample_id: body.sample_id,
      code: body.code,
      tests: body.tests ?? ""
    }
  };
});

const data = $input.first().json;
const code = data.code ?? data.body?.code ?? "";
const findings = [];

if (/discounts\s*=\s*\[\]/.test(code)) {
  findings.push({
    agent: "Bug Analysis",
    severity: "HIGH",
    title: "Mutable default argument",
    recommendation: "Replace discounts=[] with discounts=None."
  });
}

if (/return\s+total\s*\/\s*count/.test(code)) {
  findings.push({
    agent: "Bug Analysis",
    severity: "MEDIUM",
    title: "Potential division by zero",
    recommendation: "Validate count before division."
  });
}

return [{
  json: {
    sample_id: data.sample_id,
    bug_findings: findings
  }
}];

const data = $input.first().json;
const code = data.code ?? data.body?.code ?? "";

const src=$json.code||'';
const lines=src.split('\n');
const findings=[];
function add(rule,severity,line,title,recommendation){findings.push({agent:'security',rule,severity,line,title,recommendation});}
lines.forEach((s,i)=>{
 const line=i+1;
 if (/\bquery\s*=\s*f["'].*\b(SELECT|UPDATE|INSERT|DELETE)\b/i.test(s)) add('SEC-SQL-INJECTION','Critical',line,'Potential SQL injection','Use parameterized queries; never interpolate untrusted values into SQL.');
 if (/\b(execute|executemany|raw)\s*\(\s*f["']/.test(s) || /\bexecute\s*\([^\n]*(\+|%\s*\(|\.format\s*\()/.test(s)) add('SEC-SQL-INJECTION','Critical',line,'Potential SQL injection','Use parameterized queries; never interpolate untrusted values into SQL.');
 if (/\b(shell\s*=\s*True|os\.system\s*\()/.test(s)) add('SEC-SHELL','High',line,'Shell command execution','Use argument arrays with shell=False and validate inputs.');
 if (/\b(eval|exec)\s*\(/.test(s)) add('SEC-EVAL','Critical',line,'Dynamic evaluation of input','Remove eval/exec and parse expected data types explicitly.');
 if (/\b(password|api_key|secret|token)\s*=\s*["'][^"']{6,}["']/.test(s) && !/example|placeholder|dummy/i.test(s)) add('SEC-HARDCODED-SECRET','High',line,'Possible hardcoded credential','Use a secret manager or environment variable; rotate exposed credentials.');
 if (/\b(open|send_file)\s*\(\s*(filename|filepath|path|user_path)\b/.test(s)) add('SEC-PATH-TRAVERSAL','High',line,'Unvalidated file path','Constrain resolved paths to an approved base directory.');
});

if (/SELECT\b[^\n]*\+/.test(code)) {
  findings.push({
    agent: "security",
    rule: "SEC-SQL-INJECTION",
    severity: "CRITICAL",
    title: "Potential SQL injection",
    recommendation:
      "Use parameterized SQL queries instead of string concatenation."
  });
}

return [{json:{sample_id:$json.sample_id,agent:'security',findings}}];

const data = $input.first().json;
const code = data.code ?? data.body?.code ?? "";
const tests = data.tests ?? "";
const findings = [];

if (!String(tests).trim()) {
  findings.push({
    agent: "Test Coverage",
    severity: "MEDIUM",
    title: "No tests provided",
    recommendation: "Add unit tests for all functions."
  });
}

if (/discounts\s*=\s*\[\]/.test(code)) {
  findings.push({
    agent: "Test Coverage",
    severity: "MEDIUM",
    title: "Missing mutable-default test",
    recommendation: "Test repeated function calls."
  });
}

if (/return\s+total\s*\/\s*count/.test(code)) {
  findings.push({
    agent: "Test Coverage",
    severity: "MEDIUM",
    title: "Missing zero-divisor test",
    recommendation: "Test count = 0."
  });
}

return [{
  json: {
    sample_id: data.sample_id,
    test_findings: findings
  }
}];

const items = $input.all();
const findings = [];

for (const item of items) {
  const data = item.json;

  for (const key of [
    "bug_findings",
    "security_findings",
    "test_findings",
    "findings"
  ]) {
    if (Array.isArray(data[key])) {
      findings.push(...data[key]);
    }
  }
}

const ranks = {
  CRITICAL: 4,
  HIGH: 3,
  MEDIUM: 2,
  LOW: 1
};


for (const finding of findings) {
  finding.severity = String(
    finding.severity ?? "LOW"
  ).toUpperCase();
}

findings.sort((a, b) =>
  (ranks[b.severity] ?? 0) -
  (ranks[a.severity] ?? 0)
);

const summary = {
  critical: findings.filter(f => f.severity === "CRITICAL").length,
  high: findings.filter(f => f.severity === "HIGH").length,
  medium: findings.filter(f => f.severity === "MEDIUM").length,
  low: findings.filter(f => f.severity === "LOW").length,
  total: findings.length
};

return [{
  json: {
    sample_id: items[0]?.json.sample_id ?? "unknown",
    status: summary.high || summary.critical
      ? "CHANGES_REQUIRED"
      : "REVIEW_COMPLETE",
    summary,
    findings,
    debug: {
      received_items: items.length,
      findings_collected: findings.length,
      input_keys: items.map(i => Object.keys(i.json))
    }
  }
}];
